namespace qqworld_collector\module; use qqworld_collector\lib; class cleaner extends lib { var $options; var $module = 'cleaner'; var $settings_name = 'qqworld-collector-cleaner'; var $default_mime_types = array('image/jpeg', 'image/png', 'image/gif'); var $mime_type_pretty_name; public function __construct() { if ( !apply_filters( 'qqworld-collector-activated', false ) ) return; if ( apply_filters( 'qqworld-collector-activated-license', false ) && !apply_filters( 'qqworld-collector-activated-module-' . $this->module, false ) ) return; add_action( 'admin_menu', array($this, 'admin_menu') ); add_action( 'admin_init', array($this, 'register_settings') ); add_action( 'admin_enqueue_scripts', array($this, 'admin_enqueue_scripts') ); add_filter( 'qqworld-collector-script-translation-array', array($this, 'add_translation_array') ); add_filter( 'qqworld-collector-delete-post-meta-before-delete-post', array($this, 'delete_post_meta_before_delete_post') ); add_action( 'wp_ajax_qqworld-collector-clearner-scan-attachment', array($this, 'scan_attachment') ); add_action( 'wp_ajax_nopriv_qqworld-collector-clearner-scan-attachment', array($this, 'scan_attachment') ); add_action( 'before_delete_post', array($this, 'delete_attachments_before_delete_post') ); add_action( 'wp_ajax_qqworld-collector-delete-duplicated-posts', array($this, 'delete_duplicated_posts') ); add_action( 'wp_ajax_nopriv_qqworld-collector-delete-duplicated-posts', array($this, 'delete_duplicated_posts') ); add_action( 'wp_ajax_qqworld-collector-delete-empty-posts', array($this, 'delete_empty_posts') ); add_action( 'wp_ajax_nopriv_qqworld-collector-delete-empty-posts', array($this, 'delete_empty_posts') ); } public function admin_menu() { $parent_slug = 'qqworld-collector'; $page_title = __('Cleaner', $this->text_domain); $menu_title = $page_title; $capability = !$this->options->qc_authorization_all_roles_can_modify_settings ? 'manage_options' : $this->options->qc_authorization_who_can_use; $menu_slug = 'qqworld-collector-cleaner'; $function = array($this, 'cleaner'); $settings_page = add_submenu_page($parent_slug, $page_title, $menu_title, $capability, $menu_slug, $function); add_action( "load-{$settings_page}", array($this, 'help_tab') ); } public function register_settings() { register_setting($this->settings_name, $this->settings_name); } public function cleaner() { $this->mime_type_pretty_name = $this->get_mime_type_pretty_name(); require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cleaner.php'; } public function admin_enqueue_scripts() { $screen = get_current_screen(); if (strstr($screen->id, 'qqworld-collector-cleaner')) { wp_enqueue_style('animate'); wp_enqueue_script('noty'); wp_enqueue_style('noty'); wp_enqueue_script('jquery-sprintf'); wp_enqueue_script('qqworld-collector-cleaner-admin'); } } public function add_translation_array($translation_array) { $screen = get_current_screen(); if (strstr($screen->id, 'qqworld-collector-cleaner')) { $translation_array['text']['scanned_n_attachment'] = __('<strong id="scan-results">%s</strong> attachments have been scanned.', $this->text_domain); $translation_array['text']['are_your_sure'] = __('Are you sure?<br />Before you click the yes button, I recommend backup whole website.', $this->text_domain); $translation_array['text']['are_u_sure_delete_duplicated_posts'] = __('Are you sure to delete duplicated posts?', $this->text_domain); $translation_array['text']['are_u_sure_delete_empty_posts'] = __('Are you sure to delete empty posts?', $this->text_domain); $translation_array['text']['no_need_wait'] = __('You can close the window, no need to waiting.', $this->text_domain); $translation_array['cleaner_activated'] = apply_filters( 'qqworld-collector-activated-module-cleaner', false ); } return $translation_array; } public function check_is_exists($attachment_id, $mode) { $metadata = wp_get_attachment_metadata($attachment_id); $post_type = isset($_POST['post_type']) ? $_POST['post_type'] : array(); $sizes = array('full'); $results = array(); if (!empty($metadata['sizes'])) foreach ($metadata['sizes'] as $size => $args) { $sizes[] = $size; } if (!empty($sizes)) foreach ($sizes as $size) { $src = wp_get_attachment_image_src($attachment_id, $size); if (preg_match('/\/\d{4}\/\d{2}\/.*?$/i', $src[0], $match) ) $results[$size] = $match[0]; } $results = array_flip(array_flip($results)); $number = 0; $post_types = get_post_types(array('public' => true, 'show_ui' => true)); unset($post_types['attachment']); $exists = 0; foreach ($results as $attachment) { $ids = array(); $args = array( 'post_type' => $post_types, 's' => $attachment, 'post_status' => array('draft', 'pending', 'publish', 'future', 'private') ); query_posts($args); while ( have_posts() ) : the_post(); $exists += 1; endwhile; wp_reset_query(); } $return = array(); $return['exists'] = $exists; $featured = false; $args = array( 'post_type' => $post_types, 'meta_key' => '_thumbnail_id', 'meta_value' => $attachment_id ); query_posts($args); while ( have_posts() ) : the_post(); $featured = true; endwhile; $return['featured'] = $featured; $return['only_check_unattached'] = empty($post_type); $attach = get_post($attachment_id); $return['is_unattached'] = $attach->post_parent == 0; if (!empty($post_type)) { if ($attach->post_parent!=0) { $parent = get_post($attach->post_parent); $is_some_post_type = isset($parent->post_type) && in_array($parent->post_type, $post_type); } else $is_some_post_type = false; } else $is_some_post_type = $return['is_unattached'] == false; $return['is_some_post_type'] = $is_some_post_type; if ($return['only_check_unattached'] && !$return['is_unattached']) return false; if (!$return['only_check_unattached'] && !$is_some_post_type) return false; if (!$exists && !$featured) { if ($mode=='scan') { wp_delete_attachment( $attachment_id, true ); $return['deleted'] = true; } } else $return['deleted'] = false; if ($mode=='scan') update_post_meta($attachment_id, '_check_exists', 1); return $return; } public function scan_attachment() { global $post; $mime_types = isset($_POST['mime_types']) ? $_POST['mime_types'] : $this->default_mime_types; $count = $_POST['count']; $mode = $_POST['mode']; $attachment_id = $_POST['id']; $post = get_post($attachment_id); $type = isset($post->post_mime_type) ? $post->post_mime_type : ''; if (!in_array($type, $mime_types)) exit; setup_postdata($post); $return = $this->check_is_exists($attachment_id, $mode); if ($return) : ?>
	<tr<?php if ($count%2==0) echo ' class="alternate"'; ?>>
		<th scope="row"><a href="<?php echo get_edit_post_link($attachment_id); ?>" target="_blank"><?php echo $attachment_id; ?></a></th>
		<th scope="row">
		<?php
 if (!$return['deleted']) : if (wp_attachment_is_image($attachment_id)) { $img = wp_get_attachment_image_src($attachment_id, 'thumbnail'); $img = $img ? $img : wp_get_attachment_image_src($attachment_id, 'full'); $src = $img[0]; } else { $src = wp_mime_type_icon($type); } ?>
			<img src="<?php echo $src; ?>" height="150" />
		<?php else: if ($mode == 'scan') _e('Deleted', $this->text_domain); else { _e('Deletable', $this->text_domain); } endif; ?>
		</th>
		<th scope="row"><?php the_title(); ?></th>
		<th scope="row"><?php
 if (!$return['is_unattached']) { $p = get_post($post->post_parent); echo $p->post_type!='attachment' ? '<a href="'.admin_url('/post.php?post='.$p->ID.'&action=edit').'" target="_blank">'.$p->post_title.'</a>' : __('Unattached', $this->text_domain); } else _e('Unattached', $this->text_domain); ?></th>
		<td scope="row"><?php the_author_posts_link(); ?></td>
		<td scope="row"><?php echo $type; ?></td>
		<td scope="row"><?php the_time(get_option('date_format')); ?></td>
		<td scope="row">
			<?php
 $output = array(); if ($return['exists']) $output[] = sprintf(_n("This attachment has been found in %d post.", "This attachment has been found in %d posts.", $return['exists'], $this->text_domain), $return['exists'] ); else $output[] = __('The attachment was not found in any post contents.', $this->text_domain); if ($return['is_some_post_type']) $output[] = __('Attached to some post type.', $this->text_domain); if ($return['featured']) $output[] = __('Is featured image.', $this->text_domain); if ($return['deleted']) { $output[] = '<span style="color: red;">' . __('Deleted', $this->text_domain) . '</span>'; } elseif (!$return['exists']) { $output[] = '<a class="button button-primary delete-permanently" href="'.get_edit_post_link($attachment_id).'" target="_blank">' . __('Delete Permanently') . '</a>'; } echo implode('<br />', $output); ?>
		</td>
	<tr>
<?php
 endif; exit; } public function delete_attachments_before_delete_post($post_id) { if (!filter_var($this->options->qc_cleaner_auto_delete_enabled, FILTER_VALIDATE_BOOLEAN)) return; $mime_types = get_allowed_mime_types(); $types = array(); foreach ($mime_types as $mime_type) { $label = explode('/', $mime_type); $type = strtoupper($label[0]); $types[] = $type; } $types = array_flip(array_flip($types)); foreach ($types as $type) { $attachments = get_attached_media($type, $post_id); if (!empty($attachments)) { foreach ($attachments as $attachment_id => $attachment) { if (in_array($attachment->post_mime_type, $this->options->qc_cleaner_auto_delete_mime_types)) { wp_delete_attachment($attachment_id, true); } } } } } public function delete_duplicated_posts($post_type = null) { if (!is_user_logged_in() || !current_user_can($this->options->qc_authorization_who_can_use)) exit; global $wpdb; if ($post_type) $post_types = array( $post_type ); else extract($_POST); $count = 0; foreach ($post_types as $post_type) { $sql_1 = "CREATE TABLE `my_tmp` AS SELECT MIN(ID) AS `col1` FROM `{$wpdb->posts}` WHERE `post_type` = '{$post_type}' GROUP BY `post_title`"; $wpdb->query($sql_1); $sql_2 = "SELECT `ID` FROM `{$wpdb->posts}` WHERE `post_type` = '{$post_type}' AND `ID` NOT IN (SELECT `col1` FROM `my_tmp`)"; $results = $wpdb->get_results($sql_2); $sql_3 = "DROP TABLE `my_tmp`"; $wpdb->query($sql_3); if (!empty($results)) { $this->options->qc_cleaner_auto_delete_enabled = 0; foreach ($results as $result) { wp_delete_post($result->ID); } $count += count($results); } } if ($count) { $msg = array( 'success' => 1, 'msg' => sprintf(_n('%d duplicated post has been deleted.', '%d duplicated posts has been deleted.', $count, $this->text_domain), $count) ); } else { $msg = array( 'success' => 0, 'msg' => __('No duplicated posts found.', $this->text_domain) ); } echo json_encode($msg, JSON_INVALID_UTF8_IGNORE); exit; } public function delete_empty_posts() { if (!is_user_logged_in() || !current_user_can($this->options->qc_authorization_who_can_use)) exit; global $wpdb; extract($_POST); $sql = "SELECT `ID`,`post_type` FROM `{$wpdb->posts}` WHERE `post_content`='' AND `post_status` NOT IN ('auto-draft', 'trash')"; $results = $wpdb->get_results($sql); if (!empty($results)) { $count = count($results); foreach ($results as $result) { if (!post_type_supports($result->post_type, 'editor')) $count--; elseif (!in_array($result->post_type, $post_types)) $count--; else { $post_type = get_post_type_object($result->post_type); if ($post_type->public && $post_type->show_ui) { wp_delete_post($result->ID); } else $count--; } } $text = $count ? sprintf(_n('%d empty post has been deleted.', '%d empty posts has been deleted.', $count, $this->text_domain), $count) : __('No empty posts found.', $this->text_domain); $msg = array( 'success' => 1, 'msg' => $text ); } else { $msg = array( 'success' => 0, 'msg' => __('No empty posts found.', $this->text_domain) ); } echo json_encode($msg, JSON_INVALID_UTF8_IGNORE); exit; } public function delete_post_meta_before_delete_post($post_metas) { $post_metas[] = '_check_exists'; return $post_metas; } } ?>